<?php declare(strict_types=1);
use Kulturhus\Verein\BalanceAssetAllocation;
$assetItems=$s['journal']['asset_schedule']['items'];
$assetId=input($_GET,'asset_item');if(input($post,'action')==='balance-segment-asset')$assetId=input($post,'asset_item');
$assetItem=$assetItems[$assetId]??null;$assetShare=$allocation['asset_shares'][$assetId]??null;
?>
<section class="card" id="segment-assets"><h2><?= e($segmentText('Gemeinsam genutzte Gegenstände')) ?></h2>
<p><?= e($segmentText('Die Gegenstände bleiben einmal im Vereinsvermögen. Hier werden ihre Werte zwischen Betrieben desselben Vereinsbereichs aufgeteilt.')) ?></p>
<form method="get"><?php foreach($back as $key=>$value)echo hidden($key,$value); ?><label><?= e($segmentText('Gegenstand')) ?><select class="form-control" name="asset_item" required><option value=""><?= e($segmentText('Gegenstand auswählen …')) ?></option><?php foreach($assetItems as $id=>$item): ?><option value="<?= e($id) ?>" <?= $assetId===$id?'selected':'' ?>><?= e($item['name']??$item['receipt_number'].' · '.$id) ?></option><?php endforeach ?></select></label><button class="btn btn-solid theme-primary"><?= e($segmentText('Gegenstand öffnen')) ?></button></form>
<?php if($assetItem): ?>
<h3><?= e($assetItem['name']??$assetItem['receipt_number']) ?></h3>
<?php $assetCost=($assetItem['method']??null)==='cost';$assetDisposed=isset($assetItem['disposal'])||($assetCost&&$assetItem['book_disposals_cents']>0); ?>
<dl><dt><?= e($segmentText($assetCost?'Bewertung':'Festgelegte Abschreibung')) ?></dt><dd><?= e($segmentText(match($assetItem['method']??'linear_monthly'){'cost'=>'Anschaffungskosten mit belegten Wertänderungen','gwg_immediate'=>'Vollständig im Anschaffungsjahr (GWG)','degressive'=>'Anfangs höher, später geringer (degressiv)',default=>'Gleichmäßig über die Nutzungsdauer (linear)'})) ?></dd><dt><?= e($segmentText('Gesamter Buchwert zum Jahresende')) ?></dt><dd><?= $money($assetItem['book_closing_cents']) ?> €</dd><?php if($assetCost): ?><dt><?= e($segmentText('Wertminderung im Jahr')) ?></dt><dd><?= $money($assetItem['impairment_cents']) ?> €</dd><dt><?= e($segmentText('Wertaufholung im Jahr')) ?></dt><dd><?= $money($assetItem['writeup_cents']) ?> €</dd><?php else: ?><dt><?= e($segmentText('Gesamte Abschreibung im Jahr')) ?></dt><dd><?= $money($assetItem['depreciation_cents']) ?> €</dd><?php endif ?></dl>
<?php if(isset($assetItem['disposal'])): ?><p><strong><?= e($segmentText(match($assetItem['disposal']['kind']){'sale'=>'Verkauft','partial_scrap'=>'Teilweise ausgemustert','software_end'=>'Lizenz beendet',default=>'Vollständig ausgemustert'})) ?></strong> · <?= e($assetItem['disposal']['date']) ?></p><p><?= e($assetItem['disposal']['reason']) ?></p><?php endif ?>
<?php if($assetShare): ?><div class="table-scroll" tabindex="0" role="region" aria-label="<?= e($segmentText('Anlagenanteile')) ?>"><table class="table"><thead><tr><th><?= e($segmentText('Betrieb')) ?></th><th><?= e($segmentText('Nutzungsanteil')) ?></th><?php if($assetCost): ?><th><?= e($segmentText('Wertminderung')) ?></th><th><?= e($segmentText('Wertaufholung')) ?></th><?php else: ?><th><?= e($segmentText('Abschreibung')) ?></th><?php endif ?><?php if($assetDisposed): ?><th><?= e($segmentText('Ausgebuchter Restwert im Jahr')) ?></th><?php endif ?><th><?= e($segmentText('Buchwert zum Jahresende')) ?></th></tr></thead><tbody>
<?php foreach($assetShare['weights'] as $unit=>$weight):$assetValues=$allocation['asset_schedules'][$unit]['items'][$assetId]; ?><tr><td data-label="<?= e($segmentText('Betrieb')) ?>"><?= e($units[$unit]['name']) ?></td><td data-label="<?= e($segmentText('Nutzungsanteil')) ?>"><?= e(strtr($segmentText('{weight} von {total} {measure}'),['{weight}'=>(string)$weight,'{total}'=>(string)array_sum($assetShare['weights']),'{measure}'=>$segmentText(BalanceAssetAllocation::MEASURES[$assetShare['measure']])])) ?></td><?php if($assetCost): ?><td data-label="<?= e($segmentText('Wertminderung')) ?>"><?= $money($assetValues['impairment_cents']) ?> €</td><td data-label="<?= e($segmentText('Wertaufholung')) ?>"><?= $money($assetValues['writeup_cents']) ?> €</td><?php else: ?><td data-label="<?= e($segmentText('Abschreibung')) ?>"><?= $money($assetValues['depreciation_cents']) ?> €</td><?php endif ?><?php if($assetDisposed): ?><td data-label="<?= e($segmentText('Ausgebuchter Restwert im Jahr')) ?>"><?= $money($assetValues['book_disposals_cents']) ?> €</td><?php endif ?><td data-label="<?= e($segmentText('Buchwert zum Jahresende')) ?>"><?= $money($assetValues['book_closing_cents']) ?> €</td></tr><?php endforeach ?></tbody></table></div><p><?= e($segmentText('Nachweis:')) ?> <?= e($assetShare['reason']) ?></p><?php endif ?>
<?php $assetUseCarried=$assetCost&&($assetItem['valuation']['source']['previous']??null)!==null;if($assetUseCarried): ?><p><?= e($segmentText('Die belegten Nutzungsanteile werden unverändert aus dem vorherigen Abschluss übernommen.')) ?></p><?php endif ?>
<?php if($writer&&!$assetUseCarried):$failed=input($post,'action')==='balance-segment-asset';$measure=$failed?input($post,'measure'):($assetShare['measure']??'hours'); ?>
<details <?= !$assetShare||$failed?'open':'' ?>><summary><?= e($segmentText($assetShare?'Nutzungsaufteilung ändern':'Nutzung aufteilen')) ?></summary>
<p><?= e($segmentText('Zum Beispiel 30 Nutzungsstunden für den Getränkeverkauf und 70 für den Essensverkauf. Nur belegte Werte eintragen; nicht genutzte Betriebe leer lassen.')) ?></p>
<form method="post"><?= $segmentFields('balance-segment-asset').hidden('asset_item',$assetId) ?>
<label><?= e($segmentText('Woran wird die Nutzung gemessen?')) ?><select class="form-control" name="measure" required><?php foreach(BalanceAssetAllocation::MEASURES as $key=>$label): ?><option value="<?= e($key) ?>" <?= $measure===$key?'selected':'' ?>><?= e($segmentText($label)) ?></option><?php endforeach ?></select></label>
<?php foreach($units as $unit=>$u):if($u['sphere']!==$assetItem['sphere'])continue;$value=$failed&&is_array($post['weights']??null)?input($post['weights'],$unit):(string)($assetShare['weights'][$unit]??''); ?><label><?= e($u['name']) ?><input class="form-control" name="weights[<?= e($unit) ?>]" inputmode="numeric" pattern="[0-9]+" maxlength="7" value="<?= e($value) ?>"></label><?php endforeach ?>
<label><?= e($segmentText('Nachweis der Nutzung')) ?><input class="form-control" name="evidence" maxlength="1000" placeholder="<?= e($segmentText('z. B. Belegungsplan des Jahres')) ?>" value="<?= e($failed?input($post,'evidence'):($assetShare['reason']??'')) ?>" required></label>
<label class="check"><input class="check" type="checkbox" name="reviewed" value="1" required <?= $segmentReviewed('balance-segment-asset')?'checked':'' ?>><?= e($segmentText('Die Nutzungsanteile sind belegt. Der steuerliche Vereinsbereich bleibt unverändert.')) ?></label><button class="btn btn-solid theme-primary"><?= e($segmentText('Nutzungsaufteilung speichern')) ?></button></form>
<p><?= e($segmentText('Bei Nutzung in unterschiedlichen steuerlichen Vereinsbereichen muss die Buchhaltung die Vermögens- und Kostenzuordnung getrennt klären.')) ?></p></details><?php endif;endif ?>
</section>
